<script setup>
import ProviderAccessGate from './ProviderAccessGate.vue'
import VerifiedSignup from './VerifiedSignup.vue'
import FirebasePush from './FirebasePush.vue'
const newGoogleSignup=new URLSearchParams(location.search).get('verified_signup')==='1'
const firebaseTestPage=new URLSearchParams(location.search).get('firebase_test')==='1'
import BrandLogo from '../BrandLogo.vue'
import RoleWelcome from '../learning/RoleWelcome.vue'
import '@fontsource-variable/manrope'
import {ref,defineAsyncComponent,onMounted} from 'vue'
import Icon from '../Icon.vue'
import '../brand.css'
import MobileVerification from './MobileVerification.vue'
import {request} from './client'
const OperatorWorkspace=defineAsyncComponent(()=>import('./AdvancedWorkspace.vue'))
const Campus=defineAsyncComponent(()=>import('../App.vue'))
const ControlPlane=defineAsyncComponent(()=>import('./ControlPlane.vue'))
const Subscription=defineAsyncComponent(()=>import('./Subscription.vue'))
const Owner=defineAsyncComponent(()=>import('./SuperAdmin.vue'))
const Profile=defineAsyncComponent(()=>import('../commerce/ProfileEditor.vue'))
const Signup=defineAsyncComponent(()=>import('./RegistrationFlow.vue'))
const AccountSubscription=defineAsyncComponent(()=>import('./SubscriptionBilling.vue'))
const subscription=ref(null),policy=ref({})
const session=ref(null),error=ref(''),busy=ref(true),selected=ref('Student'),signup=ref(new URLSearchParams(location.search).get('signup')==='1'),dark=ref(false)
const roles=[{name:'Student',icon:'GraduationCap',text:'Learn, explore and grow.'},{name:'Teacher',icon:'BookOpen',text:'Your own teaching space.'},{name:'Institute',icon:'Building2',text:'Your teachers and classrooms.'}]
function openSignup(){sessionStorage.setItem('sisu_signup_role',selected.value==='Teacher'?'Individual Teacher':selected.value);signup.value=true}
async function google(){try{const r=await request('portal_policy','google_start');const u=new URL(r.url);if(u.protocol!=='https:'||u.hostname!=='accounts.google.com')throw Error('Google sign-in is unavailable');location.assign(u.href)}catch(e){error.value=e.message}}
async function connect(){busy.value=true;error.value='';try{session.value=await request('portal_session','current',{},'GET');if(session.value.csrf_token)window.csrf_token=session.value.csrf_token;if(session.value.member)subscription.value=(await request('account_billing','status')).account}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>{if(!firebaseTestPage){connect();request('portal_policy','public',{},'GET').then(p=>policy.value=p).catch(()=>{})}})
</script>
<template>
<section v-if="firebaseTestPage" class="panel" style="max-width:760px;margin:40px auto;padding:24px"><h1>SISU browser notification test</h1><p>This test uses your configured sandbox account.</p><a href="/sandbox_firebase_login">Sign in as sandbox Administrator</a><FirebasePush/></section>
  <ControlPlane v-else-if="session?.control_plane&&session.role==='Super Admin'"/>
  <Subscription v-else-if="session?.control_plane&&session.authenticated" control-plane/>
  <ProviderAccessGate v-else-if="session?.member&&session.role!=='Student'&&(!subscription||(subscription.workspace_available??subscription.available)===false)" :role="session.role" @changed="connect"/><AccountSubscription v-else-if="session?.member&&(!subscription||(subscription.workspace_available??subscription.available)===false)" standalone @changed="connect"/>
  <Owner v-else-if="session?.role==='Super Admin'" :session="session"/>
  <OperatorWorkspace v-else-if="session?.role==='Operator'" standalone/>
  <Campus v-else-if="session?.member"/>
  <VerifiedSignup v-else-if="session?.authenticated && policy.self_signup_enabled && newGoogleSignup" :policy="policy" google-session @back="connect"/><div v-else-if="session?.authenticated" class="entry-onboarding"><h1>Let’s make this space yours.</h1><p>Complete your profile and mobile verification before your workspace is activated.</p><p>Account type: {{session.onboarding_kind}}</p><MobileVerification/><Profile :key="session.onboarding_kind" :member="{user:session.user,full_name:session.user,role:session.onboarding_kind==='Institute'?'Admin':session.onboarding_kind}" @saved="connect"/><a href="/me">Account settings</a><a href="/api/method/logout">Sign out</a></div>
  <Signup v-else-if="signup" @back="signup=false" @dashboard="connect"/>
  <main v-else class="sisu-entry" :class="{'entry-dark':dark}">
    <header><a href="#" class="entry-brand"><BrandLogo/></a><div><span class="entry-note">A little space. A world of possibility.</span><button class="entry-icon" @click="dark=!dark" :aria-label="dark?'Light mode':'Dark mode'"><Icon :name="dark?'Sun':'Moon'"/></button></div></header>
    <div class="entry-layout"><section class="entry-story"><span class="entry-kicker">YOUR NEXT CHAPTER STARTS HERE</span><h1>Big dreams.<br>Little steps.<br><em>Your space.</em></h1><p>A calm home for learning, teaching and all the wonderful things you’ll become.</p><div class="entry-garden" aria-hidden="true"><span class="entry-orbit"></span><div class="entry-book"><Icon name="BookOpen" :size="75"/><span>Keep growing.</span></div><span class="garden-spark">✧</span><span class="garden-leaf">❧</span><span class="garden-dot"></span></div><footer><span>✦ A place to belong</span><span>Made for curious minds</span></footer></section>
    <section class="entry-card"><span class="entry-kicker">COME ON IN</span><h2>It’s good to see you.</h2><p>Choose your space to get started.</p><div class="entry-roles"><button v-for="r in roles" :key="r.name" @click="selected=r.name" :class="{selected:selected===r.name}" :aria-pressed="selected===r.name"><span><Icon :name="r.icon" :size="21"/></span><div><strong>{{r.name}}</strong><small>{{r.text}}</small></div><i>{{selected===r.name?'✓':'›'}}</i></button></div>
      <RoleWelcome :role="selected"/><a v-if="policy.self_signup_enabled" class="entry-primary" href="/login?redirect-to=/campus">Sign in with email and password →</a><button v-if="policy.self_signup_enabled||selected==='Student'" class="entry-primary entry-google" :disabled="!policy.google_available" @click="google"><img :src="'/assets/frappe/icons/social/google.svg'" alt="" width="20" height="20"/>Continue with Google</button><p v-if="!policy.google_available" class="entry-subtle">Google sign-in is not available yet. Use email and password.</p><a v-if="!policy.self_signup_enabled&&selected!=='Student'" class="entry-primary" href="/login?redirect-to=/campus">Sign in as provider →</a><p class="entry-secure"><Icon name="ShieldCheck" :size="15"/>Your account determines your permissions.</p><div class="entry-divider"><span>NEW TO SISU?</span></div><button class="entry-secondary" @click="openSignup">Create your account <Icon name="Plus" :size="16"/></button><p class="entry-subtle">{{policy.self_signup_enabled?'Verify your email and phone, create your password, then sign in.':'Students use Google. Teachers and institutes apply for review, then set a password through a secure email.'}}</p><details class="entry-owner"><summary>Platform owner access</summary><a href="/login?redirect-to=/campus">Sign in to Super Admin →</a><p>Only the configured, verified owner account can access the separate control room.</p></details>
      <div v-if="error" class="entry-status" role="status"><span class="status-dot"></span><div><strong>Connection or account issue</strong><p>{{error}}</p><button @click="connect" :disabled="busy">Check connection again</button></div></div><p v-else-if="busy" role="status">Checking your session…</p>
    </section></div><footer class="entry-bottom">{{policy.self_signup_enabled?'Teachers and institutes select and pay for a plan before workspace access.':'One 14-day trial per new account. Then a monthly subscription.'}}<span>Secure access · No sample accounts</span></footer>
  </main>
</template>
<style>
.sisu-entry{--entry-bg:rgb(108 106 238 / 6%);--entry-card:#fffcff;--entry-ink:#3b3050;--entry-muted:#7b708b;--entry-border:rgb(108 106 238 / 12%);min-height:100vh;background:var(--entry-bg);color:var(--entry-ink);padding:34px max(28px,6vw);font-family:Inter,system-ui,sans-serif}.sisu-entry.entry-dark{--entry-bg:#201a2d;--entry-card:#2c243b;--entry-ink:rgb(108 106 238 / 6%);--entry-muted:#b3a5c5;--entry-border:#453854}.sisu-entry header,.sisu-entry header>div,.entry-bottom,.entry-story footer{display:flex;align-items:center;justify-content:space-between;gap:25px}.entry-brand{font-size:39px;font-weight:800;letter-spacing:-3px;color:inherit;text-decoration:none}.entry-brand span{color:#6C6AEE;font-size:22px;margin-left:8px}.entry-note{font-size:12px;color:var(--entry-muted)}.entry-icon{background:var(--entry-card);border:1px solid var(--entry-border);border-radius:50%;padding:12px;color:inherit;cursor:pointer}.entry-layout{display:grid;grid-template-columns:1.1fr 1fr;gap:9%;max-width:1240px;margin:70px auto 50px;align-items:center}.entry-kicker{font-size:10px;letter-spacing:2.7px;font-weight:600;color:var(--entry-muted)}.entry-story h1{font-size:clamp(44px,5vw,74px);line-height:1.12;letter-spacing:-3px;margin:27px 0}.entry-story h1 em{color:#6C6AEE;font-style:normal}.entry-story>p{max-width:365px;color:var(--entry-muted);font-size:15px;line-height:1.9}.entry-garden{position:relative;height:210px;margin:20px 0;display:grid;place-items:center;max-width:370px}.entry-book{width:150px;height:166px;background:linear-gradient(150deg,rgb(108 106 238 / 8%),#6C6AEE);border:5px solid #fff8;border-radius:26px 38px 28px 12px;box-shadow:15px 16px 0 #6C6AEE3a,20px 24px 35px #6C6AEE1c;transform:rotate(-10deg);display:flex;align-items:center;justify-content:center;gap:13px;flex-direction:column;color:#755398}.entry-book span{font-size:12px;font-weight:600}.entry-orbit{position:absolute;width:310px;height:145px;border:1px solid #6C6AEE60;border-radius:50%;transform:rotate(-20deg)}.garden-spark{position:absolute;right:25px;top:15px;color:#6C6AEE;font-size:62px}.garden-leaf{position:absolute;left:0;bottom:0;color:#88a797;font-size:120px;transform:rotate(-30deg)}.garden-dot{width:22px;height:22px;background:#e7c59d;border-radius:50%;position:absolute;bottom:30px;right:38px}.entry-story footer{justify-content:flex-start;font-size:11px;color:var(--entry-muted)}.entry-card{padding:38px;border:1px solid var(--entry-border);border-radius:30px;background:var(--entry-card);box-shadow:0 25px 70px #6a43860b}.entry-card h2{font-size:30px;letter-spacing:-1px;margin:14px 0}.entry-card>p{font-size:13px;color:var(--entry-muted);line-height:1.7}.entry-roles{display:grid;gap:10px;margin:26px 0}.entry-roles button{display:flex;align-items:center;gap:14px;width:100%;padding:15px;border:1px solid var(--entry-border);border-radius:15px;background:transparent;color:inherit;cursor:pointer;text-align:left}.entry-roles button.selected{background:#6C6AEE1a;border-color:#6C6AEE}.entry-roles button>span{background:#6C6AEE19;padding:10px;border-radius:12px;color:#6C6AEE}.entry-roles button div{display:grid;gap:5px;flex:1}.entry-roles strong{font-size:13px}.entry-roles small{font-size:11px;color:var(--entry-muted)}.entry-roles i{font-style:normal;color:#6C6AEE}.entry-primary,.entry-google{margin-top:14px;background:#fff;color:#443153;border:1px solid #c4bbd5;box-shadow:none}.entry-google:disabled{opacity:.55;cursor:not-allowed}.entry-secondary{display:flex;align-items:center;justify-content:center;gap:15px;border-radius:13px;padding:16px;font-size:13px;font-weight:600;width:100%;text-decoration:none;cursor:pointer}.entry-primary{background:#6C6AEE;color:#fff;box-shadow:0 7px 16px #6C6AEE20}.entry-google{margin-top:14px;background:#fff;color:#443153;border:1px solid #c4bbd5;box-shadow:none}.entry-google:disabled{opacity:.55;cursor:not-allowed}.entry-secondary{border:1px solid var(--entry-border);color:inherit;background:transparent}.entry-secure{display:flex;align-items:center;justify-content:center;gap:7px;font-size:10px!important;margin:13px 0}.entry-divider{border-top:1px solid var(--entry-border);text-align:center;margin:26px 0 20px;height:0}.entry-divider span{position:relative;top:-8px;padding:0 14px;background:var(--entry-card);font-size:9px;letter-spacing:1px;color:var(--entry-muted)}.entry-subtle{font-size:10px!important;text-align:center;margin:14px 8px}.entry-owner{font-size:11px;margin-top:24px;color:var(--entry-muted);line-height:1.7}.entry-owner summary{cursor:pointer}.entry-owner a{display:block;margin-top:12px;color:#6C6AEE}.entry-status{margin-top:18px;padding:13px;display:flex;gap:10px;border:1px solid var(--entry-border);border-radius:12px;font-size:10px;color:var(--entry-muted);line-height:1.6}.entry-status p{margin:4px 0}.entry-status button{border:0;background:none;padding:0;text-decoration:underline;color:inherit;font-size:10px;cursor:pointer}.status-dot{background:#c7a478;width:6px;height:6px;border-radius:50%;margin-top:5px;flex-shrink:0}.entry-bottom{font-size:11px;color:var(--entry-muted);max-width:1240px;margin:auto}.entry-onboarding{max-width:780px;margin:70px auto;padding:25px}.entry-onboarding>a{margin-right:20px}@media(max-width:850px){.entry-layout{gap:35px;margin-top:40px}.entry-card{padding:25px}.entry-story h1{font-size:46px}.entry-note{display:none}.entry-garden{transform:scale(.85);transform-origin:left}}@media(max-width:640px){.entry-layout{grid-template-columns:1fr;margin-top:35px}.entry-story h1{font-size:44px}.entry-story>p{font-size:13px}.entry-garden,.entry-story footer{display:none}.entry-bottom{flex-direction:column;gap:10px;text-align:center}.entry-card h2{font-size:26px}}
</style>
